function checkDescription(key,value){if(typeof value==='string')return value;const names={title:'title',authors:'authors',year:'publication year',doi:'DOI (if applicable)',journal:'journal name',journal_abbreviation:'journal abbreviation',volume:'volume',issue:'issue',pages:'article pages / locator',type:'publication type'};if(key==='headings')return value.text+' · heading level '+value.level+' · line '+value.line;if(key==='references')return value.name+' · '+(value.kind==='pdf'?'page':'section')+' '+value.page+' · line '+value.line;if(key==='document_references')return value.name+' · document reference · line '+value.line+' · '+value.marker;if(key==='mechanical_issues')return 'Line '+value.line+': '+value.reason+' · '+value.text+(value.first_line?' · first occurrence on line '+value.first_line:'');if(key==='unresolved_references')return 'Line '+value.line+': '+value.reason;if(key==='catalogue_reference_warnings')return value.name+' · source location '+value.page+' · line '+value.line+': '+value.reason;if(key==='missing_metadata')return value.name+' · missing '+(value.fields||[]).map(f=>names[f]||f.replaceAll('_',' ')).join(', ');return 'Diagnostic item';}

