function publicationIdentifier(value,allowShortPMID=false){const input=value.trim(),urlDOI=input.match(/^https?:\/\/(?:dx\.)?doi\.org\/(10\.\d{4,9}\/\S+)$/i),doi=input.match(/^(?:doi:\s*)?(10\.\d{4,9}\/\S+)$/i);if(urlDOI||doi)return {provider:'crossref',identifier:(urlDOI||doi)[1],identifier_type:'doi'};const explicit=input.match(/^(?:pmid:\s*|https?:\/\/pubmed\.ncbi\.nlm\.nih\.gov\/)([1-9]\d{0,11})\/?$/i),bare=input.match(allowShortPMID?/^([1-9]\d{0,11})$/:/^([1-9]\d{4,11})$/);return explicit||bare?{provider:'pubmed',identifier:(explicit||bare)[1],identifier_type:'pmid'}:null;}
