function parseTable(text,delimiter){
 const rows=[],row=[];let cell='',quoted=false,closedQuote=false;text=text.replace(/^\ufeff/,'');
 for(let index=0;index<text.length;index++){const ch=text[index];
  if(closedQuote&&ch!==delimiter&&ch!=='\n'&&ch!=='\r')throw new Error('Unexpected text after a closing quote. Check the CSV.');
  if(ch==='"'){if(quoted&&text[index+1]==='"'){cell+='"';index++;}else if(quoted){quoted=false;closedQuote=true;}else if(cell==='')quoted=true;else throw new Error('Quote inside an unquoted cell. Check the CSV.');}
  else if(ch===delimiter&&!quoted){row.push(cell);cell='';closedQuote=false;}
  else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[index+1]==='\n')index++;row.push(cell);rows.push(row.splice(0));cell='';closedQuote=false;}
  else cell+=ch;
 }
 if(quoted)throw new Error('CSV has an unclosed quoted cell.');if(cell||row.length||closedQuote){row.push(cell);rows.push(row);}
 if(!rows.length||!rows[0].length)throw new Error('No table cells found.');if(rows.length>500||rows[0].length>100)throw new Error('Preview supports up to 500 rows and 100 columns.');if(rows.some(r=>r.length!==rows[0].length))throw new Error('Rows have unequal numbers of cells. Check the delimiter and data.');return rows;
}
function previewTable(){const text=$('#table-text').value,delimiter=$('#table-delimiter').value==='comma'?',':'\t',rows=parseTable(text,delimiter);tablePreview={text,delimiter,rows,note:state.note,workspace:state.workspace,revision:activeEditor()?.revision,start:activeEditor()?.selectionStart,end:activeEditor()?.selectionEnd};$('#table-preview').innerHTML='<p>'+rows.length+' rows · '+rows[0].length+' columns</p><div class="matrix-table-wrap"><table class="matrix-table"><tbody>'+rows.map(row=>'<tr>'+row.map(cell=>'<td>'+escapeHTML(cell)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';$('#table-insert').disabled=false;}
function insertTable(){const review=tablePreview,editor=activeEditor();if(!review||!editor)return;if(review.text!==$('#table-text').value||review.delimiter!==($('#table-delimiter').value==='comma'?',':'\t'))return notify('The data changed. Preview the exact new rows first.',true);if(review.note!==state.note||review.workspace!==state.workspace||review.revision!==editor.revision)return notify('The draft changed. Reopen table insertion to choose a current cursor.',true);const cell=text=>text.replace(/\|/g,'\\|').replace(/\r?\n/g,' ');const lines=review.rows.map(row=>'| '+row.map(cell).join(' | ')+' |');lines.splice(1,0,'| '+review.rows[0].map(()=>'---').join(' | ')+' |');insertWriterText('\n\n'+lines.join('\n')+'\n\n',{start:review.start,end:review.end});$('#table-dialog').close();}
