function bibliographyPreviewHTML(preview){const errors=preview.errors||[];return '<p>'+preview.records.length+' valid reference metadata record(s) · '+errors.length+' invalid record(s). No paper text is imported.</p>'+errors.map(row=>'<p class="error-text" role="alert">Record '+escapeHTML(row.record_number)+' · '+escapeHTML(row.record_id||'No ID')+': '+escapeHTML(row.error)+' This record will not be imported.</p>').join('')+(preview.warnings||[]).map(w=>'<p class="transformation-warning">'+escapeHTML(w)+'</p>').join('')+preview.records.map((r,index)=>'<section class="tool-section"><strong>Record '+escapeHTML(preview.record_numbers?.[index]||index+1)+' · '+escapeHTML(r.title||r.metadata?.title||'Title unavailable')+'</strong>'+((preview.record_warnings?.[index])||[]).map(w=>'<p class="transformation-warning">'+escapeHTML(w)+'</p>').join('')+'<pre class="assist-selection">'+escapeHTML(JSON.stringify(r,null,2))+'</pre></section>').join('');}
async function previewBibliography(){if(bibliographyState.busy)return;const text=$('#bibliography-text').value,format=$('#bibliography-format').value;if(!text.trim())return notify('Choose a bibliography file or paste its text.',true);bibliographyState.busy=true;$('#bibliography-preview-button').disabled=true;try{const preview=await request('/bibliography/preview',{workspace_id:state.workspace,format,text});Object.assign(bibliographyState,{preview,text,format});$('#bibliography-preview').innerHTML=bibliographyPreviewHTML(preview);$('#bibliography-import').disabled=!preview.records.length;$('#bibliography-import').textContent=(preview.errors?.length?'Import valid records only':'Import these metadata records');}finally{bibliographyState.busy=false;$('#bibliography-preview-button').disabled=false;}}
