const figureURLs=new Map();
async function hydrateFigures(){for(const img of $$('img[data-local-figure]')){const id=img.dataset.localFigure;if(!figureURLs.has(id)){try{const response=await request('/file?id='+encodeURIComponent(id),undefined,{binary:true});figureURLs.set(id,URL.createObjectURL(await response.blob()));}catch(error){img.replaceWith(Object.assign(document.createElement('p'),{textContent:'Figure unavailable: '+error.message,className:'error-text'}));continue;}}if(img.isConnected)img.src=figureURLs.get(id);}}
async function importFigure(file){
 if(!file)return;
 try{
  const editor=activeEditor();if(!editor)return notify('Open a draft before importing a figure.',true);
  if(!/\.(png|jpe?g|webp)$/i.test(file.name)||file.size>32*1024*1024)return notify('Choose a PNG, JPG or WebP figure under 32 MB.',true);
  if(!await flushEdits())return;
  const target={workspace:editor.workspace_id,id:editor.id,revision:editor.revision,start:editor.selectionStart,end:editor.selectionEnd};
  const result=await request('/assets/import',{workspace_id:target.workspace,name:file.name,data:await fileBase64(file)}),receipt=result.results?.[0];
  if(!receipt?.document||receipt.status==='error')throw new Error(receipt?.error||'The figure import did not return a usable managed asset. No marker was inserted.');
  await refresh();
  if(state.workspace!==target.workspace||state.note!==target.id||editor.revision!==target.revision)return notify('Figure imported to the original workspace. The draft changed during import, so no marker was inserted.',true,true);
  insertWriterText('\n\n!['+file.name.replace(/[\[\]\r\n]/g,'')+'](kosh-asset:'+receipt.document.id+')\n\n',{start:target.start,end:target.end});
  notify(receipt.status==='duplicate'?'Existing local figure inserted. Its managed copy was reused.':'Local figure added. Edit its caption in Markdown.');
 }finally{$('#figure-picker').value='';}
}
async function showNoteHistory(){const editor=activeEditor();if(!editor||!await flushEdits())return;if(editor.conflict)return notify('Resolve the draft conflict before restoring a revision.',true);noteHistory=(await request('/notes/history?id='+encodeURIComponent(editor.id))).revisions||[];$('#history-content').innerHTML='<p>Restore saves an older body as a new revision. It requires the current draft version and preserves the history.</p>'+(noteHistory.length?noteHistory.map((r,i)=>'<section class="tool-section"><h3>Version '+escapeHTML(r.version)+' · '+escapeHTML(dateLabel(r.created_at))+'</h3><strong>'+escapeHTML(r.title)+'</strong><pre class="assist-selection">'+escapeHTML(r.body)+'</pre><button class="button" data-restore-revision="'+i+'">Restore this body as a new save</button></section>').join(''):'<p class="muted">No earlier revisions for this note.</p>');$('#history-dialog').dataset.note=editor.id;$('#history-dialog').dataset.version=String(editor.version);$('#history-dialog').showModal();}
async function restoreNoteRevision(index){const revision=noteHistory[index],id=$('#history-dialog').dataset.note,editor=state.editors.get(id);if(!revision||!editor||editor.dirty||editor.conflict||editor.version!==Number($('#history-dialog').dataset.version))return notify('The draft changed while history was open. Reopen history to review it again.',true);const saved=await request('/notes',{id,workspace_id:editor.workspace_id,title:editor.title,body:revision.body,version:editor.version});replaceNote(saved);state.editors.delete(id);state.note=id;$('#history-dialog').close();renderWriter();notify('Earlier body restored as a new revision.');}
async function showAssistHistory(){assistHistory=(await request('/assist/history?workspace_id='+encodeURIComponent(state.workspace))).results||[];$('#history-content').innerHTML='<p>Saved proposals remain separate from your draft. Reopen one to copy it or save an alternative; apply requires a new reviewed selection.</p>'+(assistHistory.length?assistHistory.map((r,i)=>'<section class="tool-section"><h3>'+escapeHTML(r.task)+' · '+escapeHTML(dateLabel(r.created_at))+'</h3><pre class="assist-selection">'+escapeHTML(r.proposal)+'</pre><button class="button" data-open-assist-history="'+i+'">Open proposal</button></section>').join(''):'<p class="muted">No assistance results have been saved.</p>');$('#assist-dialog').close();$('#history-dialog').showModal();}
