async function prepareAssist(){if(assistState.busy||!await flushEdits())return;const input={...assistState.input,provider:$('#assist-provider').value};if(input.note_id){const editor=state.editors.get(input.note_id);if(!editor||editor.conflict||editor.dirty)return notify('Resolve this draft conflict first.',true);input.version=editor.version;input.task=$('#assist-task').value;if(input.task==='translate')input.question=$('#assist-language').value.trim();}else if(input.task==='extract'){if(input.workspace_id!==state.workspace||!state.data.documents.some(d=>d.id===input.selected_source?.document_id&&d.workspace_id===input.workspace_id))return notify('Reopen an exact passage in the active workspace before extracting.',true);input.question=$('#extract-question').value.trim();}if(input.provider==='ollama')input.model=$('#assist-local-model').value;assistState.input=input;assistState.busy=true;renderAssist();try{assistState.preview=await request('/assist/preview',input);}finally{assistState.busy=false;renderAssist();}}
