function renderDiscovery(){const results=discovery.result?.results||[];$('#main-view').innerHTML=headline('Discover references','Type a public catalogue query. Drafts and library content are never used as a query automatically.')+'<form id="discovery-form" class="library-toolbar"><select id="discovery-provider" aria-label="Public index">'+[['pubmed','PubMed'],['crossref','Crossref'],['europepmc','Europe PMC'],['openalex','OpenAlex']].map(([v,l])=>'<option value="'+v+'" '+(discovery.provider===v?'selected':'')+'>'+l+'</option>').join('')+'</select><input class="search-field" id="discovery-query" maxlength="500" value="'+escapeHTML(discovery.query)+'" aria-label="Explicit public query" placeholder="Type a public literature query" required><button class="button primary" type="submit" '+(discovery.busy?'disabled':'')+'>'+(discovery.busy?'Searching…':'Search index')+'</button></form><p class="muted small">Your submitted query goes to the selected public index. Metadata only; no automatic full-text downloads or AI-generated searches.</p>'+(discovery.result?'<p class="muted small">'+escapeHTML(discovery.result.total)+' catalogue matches · showing '+results.length+' · '+escapeHTML(discovery.result.retrieved_at)+'</p><p>'+escapeHTML(discovery.result.notice)+'</p>'+results.map((r,i)=>'<article class="discovery-record"><h2>'+escapeHTML(r.title||'Title unavailable')+'</h2><p>'+escapeHTML(r.authors||'Authors unavailable')+'</p><p class="muted small">'+escapeHTML(r.year||'Year unavailable')+' · '+escapeHTML(r.journal||'Publication unavailable')+' · '+escapeHTML(r.doi||'DOI unavailable')+'</p><div class="row-actions">'+(/^https:\/\/[^<>\s]+$/.test(r.url||'')?'<a class="text-button" href="'+escapeHTML(r.url)+'" target="_blank" rel="noopener noreferrer">Open catalogue record</a>':'')+'<button class="button" data-literature="'+i+'">Add reference metadata</button></div></article>').join(''):empty('Find the publication first','Select an index and type a query. Adding a result saves a catalogue reference, not the full paper.'));applyHints();}
