class ApiError extends Error {constructor(message,status){super(message);this.status=status;}}
async function request(path, body, options = {}) {
  if(path==='/metadata'&&body)body={...body,expected_metadata_version:Number($('#metadata-form').dataset.version)};
  if(path==='/metadata')for(const [field] of publicationFields)body.metadata[field]=$('#meta-'+field).value;
  if(path==='/metadata'&&$('#meta-structured-authors').value===$('#metadata-form').dataset.structuredAuthors)body.metadata.author_list=JSON.parse($('#metadata-form').dataset.authorList||'[]');
  if(path==='/assist/preview'&&body?.note_id)body={...body,custom_instructions:localStorage.getItem('kosh-writing-instructions:'+body.workspace_id)||''};
  if(path==='/assist/preview'&&body?.provider==='ollama')body={...body,model:$('#assist-local-model')?.value};
  if(path==='/assist/preview'&&body?.task==='extract'){const passage=body.selected_source||selectedPassage;if(!passage)throw new Error('Select an exact extracted source passage in Read before requesting an evidence proposal.');body={...body,selected_source:passage};}
  const response = await fetch('/api' + path,{method:body === undefined?'GET':'POST',headers:{'X-App-Token':token,...(body === undefined?{}:{'Content-Type':'application/json'})},body:body === undefined?undefined:JSON.stringify(body),signal:options.signal});
  if(!response.ok){let message='Request failed ('+response.status+').';try{const result=await response.json();message=result.error||result.message||message;}catch{}throw new ApiError(typeof message==='string'?message:JSON.stringify(message),response.status);}
  return options.binary ? response : response.json();
}
