async function loadPageImage(id,page){const generation=++state.readSequence;try{const response=await request('/page?id='+encodeURIComponent(id)+'&page='+page,undefined,{binary:true});const blob=await response.blob();if(generation!==state.readSequence||state.view!=='read'||state.doc?.id!==id||state.page!==page)return;if(state.blob)URL.revokeObjectURL(state.blob);state.blob=URL.createObjectURL(blob);const canvas=$('#reader-canvas');if(canvas)canvas.innerHTML=`<img src="${state.blob}" alt="Original source page ${page}">`;}catch(error){if(generation===state.readSequence&&$('#reader-canvas'))$('#reader-canvas').innerHTML=`<p class="error-text">${escapeHTML(error.message)}</p><p class="muted">Switch to extracted text to read available content.</p>`;}}
async function openDocument(id,page=1,excerpt='',options={}){if(!await flushEdits())return;if(!options.keepPanel||innerWidth<1280)setPanelOpen(false);const generation=++state.readSequence;$('#main-view').innerHTML='<div class="loading">Opening source…</div>';try{const result=await request('/document?id='+encodeURIComponent(id));if(generation!==state.readSequence)return;state.doc=result.document?{...result.document,text_pages:result.text_pages||result.document.text_pages}:result;state.page=Math.min(Math.max(Number(page)||1,1),Math.max(state.doc.pages||state.doc.text_pages?.length||1,1));state.excerpt=excerpt;if(selectedPassage?.document_id!==id){selectedPassage=null;if(state.askScope==='passage')state.askScope='document';}state.view='read';if(state.doc.kind!=='pdf')state.readerMode='text';else state.readerMode='page';render();}catch(error){notify(error.message,true,true);renderMain();}}
function activeEditor(){return state.editors.get(state.note);}
function editorFor(note){if(!state.editors.has(note.id))state.editors.set(note.id,{id:note.id,workspace_id:note.workspace_id,title:note.title,body:note.body,version:note.version,dirty:false,revision:0,conflict:false});return state.editors.get(note.id);}
