  const inline=line=>line.replace(/!\[([^\]]*)\]\(kosh-asset:([A-Za-z0-9_-]+)\)/g,(_,caption,id)=>'<figure><img data-local-figure="'+id+'" alt="'+caption.replace(/"/g,'&quot;')+'"><figcaption>'+caption+'</figcaption></figure>').replace(/\[\[source:([^:\]]+):(\d+)\]\]/g,(_,id,page)=>{const doc=state.data.documents.find(d=>d.id===id);return doc?`<button class="citation-chip" data-source-ref="${escapeHTML(id)}:${page}">${escapeHTML(sourceLabel(doc))} · ${pageUnit(id)} ${page}</button>`:`<span class="error-text">[Unresolved source: ${escapeHTML(id)} · ${page}]</span>`;}).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/(^|[^*])\*([^*]+)\*(?!\*)/g,'$1<em>$2</em>').replace(/`([^`]+)`/g,'<code>$1</code>');
