    if(line.includes('|')&&line.trim().startsWith('|')){if(list){output+='</ul>';list=false;}if(!table){output+='<table><tbody>';table=true;}output+='<tr>'+line.trim().replace(/^\||\|$/g,'').split(/(?<!\\)\|/).map(cell=>'<td>'+inline(cell.trim().replace(/\\\|/g,'|'))+'</td>').join('')+'</tr>';continue;}
