async function flushEdits(){try{await saveAll();if(state.matrixConflict)return notify('Resolve the evidence conflict first. Your row is retained in browser recovery.',true,true),false;while(pendingEditors().length||(state.matrixDirty&&!state.matrixReview))await saveAll();return true;}catch(error){notify('Pending edits could not be saved. They remain in this window and browser recovery. '+error.message,true,true);return false;}}
async function createNote(title='Untitled note',body=''){if(creatingNote)return;if(!state.workspace)return notify('Create a workspace first.');creatingNote=true;try{if(!await flushEdits())return;const note=await request('/notes',{workspace_id:state.workspace,title,body});replaceNote(note);state.note=note.id;editorFor(note);state.view='write';state.preview=false;render();$('#draft-title')?.focus();}catch(error){notify(error.message,true,true);}finally{creatingNote=false;}}
