const matrixRecoveryKey=id=>'research-matrix-draft:'+id;
function preserveMatrix(){try{localStorage.setItem(matrixRecoveryKey(state.matrixEdit.workspace_id),JSON.stringify({edit:state.matrixEdit,revision:state.matrixRevision,conflict:!!state.matrixConflict,review:!!state.matrixReview,anchor:state.matrixReviewAnchor||null}));}catch{notify('Browser evidence recovery is unavailable. Keep this window open until saving succeeds.',true,true);}}
