function groundedChatText(chat,docs){const lookup=new Map((chat.citations||[]).filter(c=>{const doc=docs.find(d=>d.id===c.document_id);return doc&&doc.workspace_id===chat.workspace_id&&doc.kind!=='catalogue'&&Number.isInteger(c.page)&&c.page>0&&c.page<=Math.max(doc.pages||1,1);}).map(c=>[c.id,c]));let unsupported=false;const text=String(chat.answer||'').replace(/\[(C\d+(?:\s*,\s*C\d+)*)\]/g,(original,group)=>{const ids=group.split(/\s*,\s*/);if(ids.some(id=>!lookup.has(id))){unsupported=true;return original;}return ids.map(id=>{const c=lookup.get(id);return '[[source:'+c.document_id+':'+c.page+']]';}).join(' ');});const warnings=[chat.warning,...(unsupported?['Unresolved answer citation IDs remain unsupported. Check the original source.']:[]),...(chat.mode==='ollama'&&!text.includes('[[source:')?['No resolved source citations in this model answer. Treat it as unsupported.']:[])].filter(Boolean);return text+(warnings.length?'\n\n'+warnings.map(w=>'> Warning: '+w).join('\n\n'):'');}
