async function insertChatAnswer(index){const chat=state.data.chats.filter(c=>c.workspace_id===state.workspace)[index];if(!chat)return;rememberWriterSelection();const text=groundedChatText(chat,state.data.documents);if(!activeEditor())return createNote('Notes on '+String(chat.question||'source answer').slice(0,80),text+'\n\n');if(activeEditor().workspace_id!==state.workspace)return notify('Open a draft in the active workspace before inserting this answer.',true);state.view='write';insertWriterText('\n\n'+text+'\n\n');updateChrome();await saveAll().catch(()=>{});notify('Answer inserted at the saved draft cursor. Source markers and warnings are retained; check the evidence.');}
