 const totals=result.provider_totals?'<p class="muted small">Per-index reported totals (overlap; not a unique count): '+Object.entries(result.provider_totals).map(([provider,total])=>escapeHTML(labels[provider]||provider)+': '+escapeHTML(total)).join(' · ')+'</p>':'';
