  $('#main-view').innerHTML=headline('Evidence matrix','Record your own extraction. Every row stays attached to its source.','<button class="button" data-action="new-matrix">＋ New row</button>')+'<p class="evidence-intro small">Manual notes only. Entries are not verified study extraction, screening decisions or a systematic review.</p><div class="evidence-body">'+ (rows.length?`<div class="matrix-table-wrap"><table class="matrix-table"><thead><tr><th>Source</th><th>Question</th><th>Design</th><th>Findings</th><th>Limitations</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr class="${r.id===edit.id?'is-editing':''}"><td data-label="Source">${escapeHTML(sourceLabel(state.data.documents.find(d=>d.id===r.document_id)||{name:'Source unavailable'}))}</td><td data-label="Question">${escapeHTML(r.question)}</td><td data-label="Design">${escapeHTML(r.design)}</td><td data-label="Findings">${escapeHTML(r.findings)}</td><td data-label="Limitations">${escapeHTML(r.limitations)}</td><td><button class="text-button" data-matrix="${escapeHTML(r.id)}">Edit</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No rows yet. Add a source and record what you found.</p>')+(docs.length?`<form id="matrix-form" class="matrix-form"><h3>${edit.id?'Edit evidence row':'Add an evidence row'}</h3><label for="matrix-source">Source</label><select id="matrix-source">${docs.map(d=>`<option value="${escapeHTML(d.id)}" ${edit.document_id===d.id?'selected':''}>${escapeHTML(sourceLabel(d))}</option>`).join('')}</select><label for="matrix-question">Question / population</label><textarea id="matrix-question" rows="2">${escapeHTML(edit.question)}</textarea><label for="matrix-design">Study design</label><input id="matrix-design" value="${escapeHTML(edit.design)}"><div class="field-pair"><div><label for="matrix-findings">Findings</label><textarea id="matrix-findings" rows="4">${escapeHTML(edit.findings)}</textarea></div><div><label for="matrix-limitations">Limitations / uncertainty</label><textarea id="matrix-limitations" rows="4">${escapeHTML(edit.limitations)}</textarea></div></div><button class="button primary" type="submit">Save evidence row</button></form>`:empty('Import a source first','Evidence rows need an imported document to link back to.','<button class="button" data-action="import">Import sources</button>'))+'</div>';applyHints();
