function enhanceWriter(){const editor=activeEditor();if(!editor||!$('.draft-editor'))return;const refs=$('.draft-refs');if(refs){const parts=refs.innerHTML.split('<h3>Source references</h3>');refs.innerHTML='<h3>Outline</h3><div id="writer-headings"></div><h3>Source references</h3>'+(parts[1]||'');}$('.editor-toolbar', $('.draft-editor')).insertAdjacentHTML('beforeend','<button class="text-button" data-action="note-history">Revision history</button><span id="writer-word-count" class="muted small"></span>');$('.writer-export').insertAdjacentHTML('afterend','<div class="format-toolbar" aria-label="Markdown formatting">'+[['bold','Bold'],['italic','Italic'],['heading','Heading'],['list','List'],['table','Table'],['quote','Quote'],['code','Code']].map(([kind,label])=>'<button class="text-button" data-format="'+kind+'" '+(state.preview?'disabled':'')+'>'+label+'</button>').join('')+'<button class="text-button" data-action="figure-import">Add local figure</button></div>');$('.outline-menu').insertAdjacentHTML('beforeend','<button class="text-button" data-action="outline-protocol">Blank protocol</button><button class="text-button" data-action="outline-casereport">Blank case report</button>');updateWriterMetrics();}
