$('#csl-retrieve-style').addEventListener('click',()=>retrieveCsl('style'));$('#csl-retrieve-locale').addEventListener('click',()=>retrieveCsl('locale'));$('#csl-retrieve-dependencies').addEventListener('click',()=>retrieveCsl('dependencies'));
$('#csl-import-locale').addEventListener('click',()=>localePicker.click());
localePicker.addEventListener('change',async()=>{const file=localePicker.files[0];if(!file)return;try{if(file.size>1024*1024)throw new Error('Choose a locale XML file under 1 MiB.');cslRetrievalBusy=true;updateCslRetrievalButtons();$('#csl-retrieval-status').textContent='Importing local locale…';await request('/citation/locales/import',{xml:await file.text()});await loadCitationStyles();if(exportCapabilities){exportCapabilities=await request('/export/options');renderExportOptions();}$('#csl-retrieval-status').textContent='Locale imported locally. No network request was made.';}catch(error){$('#csl-retrieval-status').textContent=error.message;notify(error.message,true,true);}finally{cslRetrievalBusy=false;updateCslRetrievalButtons();localePicker.value='';}});
$('#export-options-section').addEventListener('input',event=>{if(event.target.matches('[data-template-option],#export-citation_language,#export-note_placement,#export-word_style'))captureExportOptions();});
$('#export-options-section').addEventListener('change',event=>{if(event.target.matches('[data-template-option],#export-citation_language,#export-note_placement,#export-word_style'))captureExportOptions();});
$('#export-options-section').addEventListener('click',event=>{if(event.target.id==='export-reset-options'){localStorage.removeItem(exportPreferenceKey());renderExportOptions();notify('Export preferences reset for this workspace.');}});
$('#tools-dialog').addEventListener('close',()=>{captureExportOptions();$('#csl-network-consent').checked=false;updateCslRetrievalButtons();});
$('#help-dialog .help-grid').append($('#manuscript-export-help').content.cloneNode(true));
cslImportButton.addEventListener('click',()=>cslPicker.click());
cslPicker.addEventListener('change',async()=>{const file=cslPicker.files[0];if(!file)return;try{if(file.size>1024*1024)throw new Error('Choose a CSL file under 1 MiB.');cslImportButton.disabled=true;const response=await request('/citation/styles/import',{xml:await file.text()});citationStyles=response.styles;citationStyle=response.style.id;localStorage.setItem('kosh-citation-style',citationStyle);$$('#citation-style,#tools-citation-style').forEach(el=>el.innerHTML=citationOptions());notify('Journal style imported: '+response.style.title);}catch(error){notify(error.message,true,true);}finally{cslImportButton.disabled=false;cslPicker.value='';}});
$('#tools-citation-style').parentElement.querySelector(':scope > .muted.small').textContent='Offline CSL formatting: Vancouver (NLM), APA 7 and IEEE, or imported journal styles. Missing parent styles and languages need an explicit approved retrieval or local import. Review publication metadata before submission.';
(async()=>{try{if(!token)throw new Error('Launch Kosh from its desktop launcher to authenticate this session.');await refresh();await loadCitationStyles();try{exportCapabilities=await request('/export/options');renderExportOptions();}catch(error){$('#export-options-content').textContent='Export options unavailable: '+error.message;}render();await loadModels();await loadAgentProviders();if(!localStorage.getItem('kosh-guide-seen'))showGuide();applyHints();}catch(error){notify(error.message,true,true);$('#main-view').innerHTML=empty('The local workspace is unavailable',error.message);document.body.classList.add('offline');$('#workspace-status').textContent='Connection unavailable';}})();
